INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Nassi-Shneiderman-Diagramm nur für komplexe Programme sinnvoll?', 2, '[{"text": "Nein", "correct": true, "because": "Auch einfache Abläufe klar darstellbar"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
