('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einem Nassi-Shneiderman-Diagramm?', 5, '[{"text": "Prozessblöcke", "correct": true, "because": "Zeigen Ablaufsequenzen"}, {"text": "Entscheidungen", "correct": true, "because": "Steuern Verzweigungen"}, {"text": "Farbanimation", "correct": false, "because": "Irrelevant"}, {"text": "Komponenten", "correct": false, "because": "Komponentendiagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Nassi-Shneiderman zeigt Abläufe blockweise. b) Es ersetzt Programmablaufpläne.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Alternative, kein Ersatz"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem Nassi-Shneiderman-Diagramm?', 4, '[{"text": "Prozessschritte", "correct": false, "because": "Kern der Darstellung"}, {"text": "Verzweigungen", "correct": false, "because": "Entscheidungen zeigen"}, {"text": "UI-Design", "correct": true, "because": "Kein Ablauffaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Nassi-Shneiderman-Diagramm auch Schleifen darstellt?', 2, '[{"text": "Ja", "correct": true, "because": "Blockweise Wiederholungen"}, {"text": "Nein", "correct": false, "because": "Schleifen sind enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Symbol wähle ich für eine Entscheidung?', 3, '[{"text": "Dreieck im Block", "correct": true, "because": "Standard für Verzweigungen"}, {"text": "Rechteck", "correct": false, "because": "Nur Prozessschritt"}, {"text": "Pfeil", "correct": false, "because": "Nur Verbindung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten verbessern ein Nassi-Shneiderman-Diagramm?', 5, '[{"text": "Prozessblöcke", "correct": true, "because": "Zeigen Schritte"}, {"text": "Schleifenblöcke", "correct": true, "because": "Wiederholungen klar"}, {"text": "Datenfluss", "correct": false, "because": "Datenflussdiagramm"}, {"text": "Farbcodierung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Nassi-Shneiderman ist für strukturierte Abläufe. b) Es zeigt Hardwarezuordnung. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Hardware ist Verteilungsdiagramm"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein Nassi-Shneiderman-Diagramm?', 4, '[{"text": "Entscheidungen", "correct": false, "because": "Steuern Ablauf"}, {"text": "Prozessblöcke", "correct": false, "because": "Grundlage der Darstellung"}, {"text": "Netzwerkknoten", "correct": true, "because": "Verteilungsdiagramm"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Nassi-Shneiderman-Diagramm nur für Software?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Geschäftsprozesse"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
